export const ADMIN_HTML = "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><title>Writing Dashboard | When Healing Doesn't Come</title><link rel=\"icon\" href=\"/favicon.png\" type=\"image/svg+xml\"><link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\"><link rel=\"stylesheet\" href=\"/styles.css\"><style>\n.whdc-header-top{position:relative;display:flex;align-items:center;justify-content:space-between}\n.whdc-menu-button{display:inline-flex;align-items:center;justify-content:center;width:46px;height:44px;padding:9px;border:1px solid #cbd8d4;border-radius:9px;background:#f5f8f6;cursor:pointer}\n.whdc-menu-icon{display:flex;flex-direction:column;gap:5px}.whdc-menu-icon span{display:block;width:23px;height:2px;background:#393f4a;border-radius:2px}\n.whdc-nav[hidden]{display:none!important}.whdc-nav{position:absolute;z-index:1000;top:100%;right:0;width:190px;max-width:100vw;padding:9px;background:#f5f8f6;border:1px solid #d3ded9;border-radius:10px;box-shadow:0 9px 24px #0002;display:flex;flex-direction:column;gap:3px}\n.whdc-nav .navbtn{display:block;width:100%;box-sizing:border-box;text-align:center;text-decoration:none;padding:11px 10px;border-radius:7px;color:#393f4a;transition:background .15s,color .15s}\n.whdc-nav .navbtn:hover,.whdc-nav .navbtn:focus-visible{background:#dce8e5;color:#243c3d}\n.whdc-nav .navbtn[aria-current=\"page\"]{background:#4d7275;color:white}\n@media(max-width:700px){.whdc-nav{position:absolute;left:50%;right:auto;transform:translateX(-50%);width:100vw;max-width:none;border-radius:0;padding:10px 16px 16px}.whdc-nav .navbtn{padding:13px 16px}}\n</style></head><body><header><div class=\"wrap top whdc-header-top\"><a class=\"brand\" href=\"/\" aria-label=\"When Healing Doesn't Come, home\"><img class=\"header-logo\" src=\"/header-logo.png\" alt=\"When Healing Doesn't Come\"></a><button class=\"btn whdc-menu-button\" id=\"dashboardMenuToggle\" type=\"button\" aria-controls=\"dashboardMenu\" aria-expanded=\"false\" aria-label=\"Toggle navigation menu\" title=\"Menu\"><span class=\"whdc-menu-icon\" aria-hidden=\"true\"><span></span><span></span><span></span></span></button><nav id=\"dashboardMenu\" class=\"whdc-nav\" aria-label=\"Main navigation\" hidden><a class=\"navbtn\" href=\"/#home\">Home</a><a class=\"navbtn\" href=\"/#today\">Today</a><a class=\"navbtn\" href=\"/#topics\">Topics</a><a class=\"navbtn\" href=\"/#saved\">Saved</a><a class=\"navbtn\" href=\"/#history\">Log</a><a class=\"navbtn\" href=\"/#support\">Give</a><a class=\"navbtn\" href=\"/#contact\">Contact</a><a class=\"navbtn\" href=\"/#settings\">Settings</a><a class=\"navbtn\" href=\"/cdn-cgi/access/logout\">Log Out</a></nav></div></header><main class=\"wrap\"><section class=\"hero\"><div class=\"eyebrow\">Private writer's workspace</div><h1>Writing Dashboard</h1><p>Write gently. Save a draft whenever you need to stop. Publish when you're ready.</p></section><div id=\"adminApp\" role=\"status\">Loading your devotionals…</div></main><script src=\"/admin/client.js\" defer></script></body></html>\n";
export const ADMIN_JS = "const $=s=>document.querySelector(s),safe=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nlet items=[],editing=null,writerName='Heather Kusunoki';\nasync function api(path,opts={}){const r=await fetch(path,{credentials:'same-origin',cache:'no-store',...opts});let data;try{data=await r.json()}catch{throw Error('Server returned an unexpected response')}if(!r.ok)throw Error(data.error||'Request failed');return data}\nconst scriptureUrl=reference=>'https://www.biblegateway.com/passage/?search='+encodeURIComponent(reference)+'&version=WEB';\nconst message=(s,err=false)=>{let n=$('#message');if(n){n.textContent=s;n.style.color=err?'#9b3d36':''}};\nfunction formatted(s){return safe(s).replace(/\\*\\*([^*\\n]+)\\*\\*/g,'<strong>$1</strong>').replace(/(^|[^*])\\*([^*\\n]+)\\*/g,'$1<em>$2</em>')}\nfunction paragraphs(s){return String(s||'').split(/\\n\\s*\\n/).map(t=>`<p>${formatted(t).replace(/\\n/g,'<br>')}</p>`).join('')}\nfunction formatSelection(field,mark){const el=$(`#editor textarea[name=\"${field}\"]`);if(!el)return;const a=el.selectionStart,b=el.selectionEnd,selected=el.value.slice(a,b),placeholder=mark==='**'?'bold text':'italic text',inside=selected||placeholder;el.setRangeText(mark+inside+mark,a,b,'select');el.focus();el.setSelectionRange(a+mark.length,a+mark.length+inside.length)}\nfunction wireFormatting(){document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>formatSelection(b.dataset.field,b.dataset.format));document.querySelectorAll('#editor textarea[name=\"short\"],#editor textarea[name=\"deeper\"],#editor textarea[name=\"reflection\"]').forEach(el=>el.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&!e.altKey&&['b','i'].includes(e.key.toLowerCase())){e.preventDefault();formatSelection(el.name,e.key.toLowerCase()==='b'?'**':'*')}}))}\nfunction form(d){return `<form class=\"card\" id=\"editor\"><h2>${d?'Edit':'New'} devotional</h2><label>Title<input name=\"title\" maxlength=\"150\" required value=\"${safe(d?.title||'')}\"></label><label>Author<input name=\"author\" maxlength=\"120\" required value=\"${safe(d?.author||writerName)}\"></label><p class=\"small muted\">Prefilled for new devotionals. You can change this to credit a guest writer.</p><label>Day number<input name=\"day\" type=\"number\" min=\"1\" required value=\"${safe(d?.day||items.length+1)}\"></label><label>Topics (comma separated)<input name=\"topics\" value=\"${safe((d?.topics||[]).join(', '))}\"></label><label>Scripture reference<input name=\"reference\" required value=\"${safe(d?.reference||'')}\"></label><label>Short devotional<div class=\"actions\" role=\"toolbar\" aria-label=\"Format Short devotional\"><button class=\"btn\" type=\"button\" data-field=\"short\" data-format=\"**\" title=\"Bold (Cmd/Ctrl+B)\"><strong>B</strong></button><button class=\"btn\" type=\"button\" data-field=\"short\" data-format=\"*\" title=\"Italic (Cmd/Ctrl+I)\"><em>I</em></button></div><textarea name=\"short\" rows=\"9\" required>${safe(d?.short||'')}</textarea></label><label>Go Deeper study<div class=\"actions\" role=\"toolbar\" aria-label=\"Format Go Deeper study\"><button class=\"btn\" type=\"button\" data-field=\"deeper\" data-format=\"**\" title=\"Bold (Cmd/Ctrl+B)\"><strong>B</strong></button><button class=\"btn\" type=\"button\" data-field=\"deeper\" data-format=\"*\" title=\"Italic (Cmd/Ctrl+I)\"><em>I</em></button></div><textarea name=\"deeper\" rows=\"13\" required>${safe(d?.deeper||'')}</textarea></label><label>Questions for Reflection (optional)<div class=\"actions\" role=\"toolbar\" aria-label=\"Format Questions for Reflection\"><button class=\"btn\" type=\"button\" data-field=\"reflection\" data-format=\"**\" title=\"Bold (Cmd/Ctrl+B)\"><strong>B</strong></button><button class=\"btn\" type=\"button\" data-field=\"reflection\" data-format=\"*\" title=\"Italic (Cmd/Ctrl+I)\"><em>I</em></button></div><textarea name=\"reflection\" rows=\"9\" placeholder=\"What is God inviting you to consider today?\">${safe(d?.reflection||'')}</textarea></label><div class=\"actions\"><button class=\"btn primary\" type=\"submit\" data-status=\"draft\">Save Draft</button><button class=\"btn\" type=\"submit\" data-status=\"published\">Publish</button><button class=\"btn\" type=\"button\" id=\"preview\">Preview</button><button class=\"btn\" type=\"button\" id=\"cancel\">Cancel</button></div><div id=\"previewPane\"></div></form>`}\nfunction getItem(status='draft'){const f=$('#editor');if(!f.reportValidity())return null;const v=new FormData(f);return {id:editing||'devotional-'+Date.now(),title:v.get('title').trim(),author:v.get('author').trim(),day:Number(v.get('day')),topics:v.get('topics').split(',').map(x=>x.trim()).filter(Boolean),reference:v.get('reference').trim(),bibleUrl:scriptureUrl(v.get('reference').trim()),short:v.get('short').trim(),deeper:v.get('deeper').trim(),reflection:v.get('reflection').trim(),status}}\nfunction preview(){const d=getItem();if(!d)return;const p=$('#previewPane');p.innerHTML=`<div class=\"deep\"><h2>${safe(d.title)}</h2><div class=\"scripture\">${safe(d.reference)}</div>${paragraphs(d.short)}<h3>Go Deeper</h3>${paragraphs(d.deeper)}<h3>Questions for Reflection</h3>${d.reflection?paragraphs(d.reflection):'<p>No reflection questions added.</p>'}<p class=\"small muted\">Written by ${safe(d.author)}</p></div>`;p.scrollIntoView({behavior:'smooth'})}\nfunction edit(d){editing=d?.id||null;$('#editArea').innerHTML=form(d);$('#editor').scrollIntoView({behavior:'smooth'});wireFormatting();$('#cancel').onclick=()=>{$('#editArea').innerHTML='';editing=null};$('#preview').onclick=preview;$('#editor').onsubmit=async e=>{e.preventDefault();const status=e.submitter?.dataset.status||'draft';const item=getItem(status);if(!item)return;if(status==='published'&&!confirm('Publish this devotional to the public website?'))return;try{await api('/api/admin/devotionals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(item)});editing=null;await refresh();message(status==='published'?'Published successfully.':'Draft saved.')}catch(err){message(err.message,true)}}}\nasync function refresh(){try{items=await api('/api/admin/devotionals');render()}catch(e){$('#adminApp').innerHTML=`<div class=\"notice warning\">Unable to open your private dashboard: ${safe(e.message)}. Check the Access settings and Worker variables.</div>`}}\nfunction exportDevotionals(format){\n if(!items.length){message('There are no devotionals to export yet.',true);return}\n const columns=['id','day','title','topics','reference','bibleUrl','short','deeper','reflection','status','created_at','updated_at'];\n const rows=items.map(d=>Object.fromEntries(columns.map(k=>[k,k==='topics'?(Array.isArray(d.topics)?d.topics.join(', '):d.topics||''):(d[k]??'')])));\n const cell=v=>'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"';\n const csv=[columns.map(cell).join(','),...rows.map(r=>columns.map(k=>cell(r[k])).join(','))].join('\\r\\n');\n const json=JSON.stringify({exportedAt:new Date().toISOString(),devotionals:items},null,2);\n const isCsv=format==='csv';\n const blob=new Blob([isCsv?'\\uFEFF'+csv:json],{type:isCsv?'text/csv;charset=utf-8':'application/json;charset=utf-8'});\n const url=URL.createObjectURL(blob),a=document.createElement('a');\n a.href=url;a.download='WHDC-devotionals-'+new Date().toISOString().slice(0,10)+(isCsv?'.csv':'.json');\n document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);\n message('Exported '+items.length+' devotionals as '+(isCsv?'CSV':'JSON')+'.');\n}\nfunction exportPdf(){\n if(!items.length){message('There are no devotionals to export yet.',true);return}\n const ordered=[...items].sort((a,b)=>(Number(a.day)||0)-(Number(b.day)||0)||String(a.title||'').localeCompare(String(b.title||'')));\n const section=(heading,value)=>value?`<section><h2>${heading}</h2>${paragraphs(value)}</section>`:'';\n const pages=ordered.map(d=>`<article class=\"devotional\">\n  <div class=\"meta\">Day ${safe(d.day)} · ${safe(Array.isArray(d.topics)?d.topics.join(', '):d.topics||'Uncategorized')}${d.status!=='published'?' · DRAFT':''}</div>\n  <h1>${safe(d.title||'Untitled')}</h1>\n  <div class=\"reference\">${safe(d.reference||'')}</div>\n  ${section('Short Devotional',d.short)}\n  ${section('Go Deeper',d.deeper)}\n  ${section('Questions for Reflection',d.reflection)}\n </article>`).join('');\n const html=`<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><title>When Healing Doesn't Come | Devotionals</title><style>\n @page{size:letter;margin:0.8in 0.85in 0.75in}\n *{box-sizing:border-box}body{font-family:Georgia,'Times New Roman',serif;color:#222;line-height:1.55;font-size:11pt;margin:0}\n .cover{text-align:center;padding-top:2.1in;break-after:page;page-break-after:always}\n .cover h1{font-size:27pt;font-weight:normal;line-height:1.2}.cover p{font-size:12pt;color:#555}\n .devotional{break-before:page;page-break-before:always}\n .meta{font:10pt Arial,sans-serif;color:#555;margin-bottom:15pt;letter-spacing:.02em}\n h1{font-size:21pt;line-height:1.25;margin:0 0 9pt;font-weight:normal}\n .reference{font-style:italic;color:#555;margin-bottom:24pt}\n h2{font: bold 12pt Arial,sans-serif;margin:22pt 0 8pt;break-after:avoid;page-break-after:avoid}\n p{margin:0 0 11pt;white-space:normal;overflow-wrap:anywhere}\n section{margin-bottom:15pt}strong{font-weight:bold}em{font-style:italic}\n @media screen{body{max-width:760px;margin:30px auto;padding:0 25px}.cover{min-height:600px}.devotional{border-top:1px solid #ddd;padding-top:30px;margin-bottom:70px}}\n </style></head><body><div class=\"cover\"><h1>When Healing Doesn't Come</h1><p>Devotional Manuscript</p><p>${ordered.length} devotionals · ${new Date().toLocaleDateString()}</p></div>${pages}</body></html>`;\n const w=window.open('','_blank');\n if(!w){message('Please allow pop-ups for this site, then try Export PDF again.',true);return}\n w.document.open();w.document.write(html);w.document.close();\n w.focus();\n message('Manuscript opened in a new tab. Choose Print, then Save as PDF.');\n}\nasync function importBulkDevotionals(e){\n const input=e.target,file=input.files?.[0];\n if(!file)return;\n input.value='';\n let entries;\n try{\n  const raw=JSON.parse(await file.text());\n  entries=Array.isArray(raw)?raw:raw?.devotionals;\n  if(!Array.isArray(entries)||!entries.length)throw Error('Choose a JSON file containing a nonempty devotionals array.');\n  if(entries.length>500)throw Error('Please import no more than 500 devotionals at a time.');\n }catch(err){message('Import failed: '+err.message,true);return}\n const existingIds=new Set(items.map(x=>String(x.id)));\n const existingDays=new Set(items.map(x=>Number(x.day)));\n const seenIds=new Set(),seenDays=new Set();\n const valid=[],skipped=[];\n for(const d of entries){\n  if(!d||typeof d!=='object'||Array.isArray(d)){skipped.push('invalid entry');continue}\n  const id=String(d.id||'').trim(),day=Number(d.day);\n  if(!id||!Number.isSafeInteger(day)||day<1||!String(d.title||'').trim()||!String(d.reference||'').trim()||!String(d.short||'').trim()||!String(d.deeper||'').trim()){\n   skipped.push('missing required fields');continue;\n  }\n  if(existingIds.has(id)||seenIds.has(id)){skipped.push('existing or duplicate ID: '+id);continue}\n  if(existingDays.has(day)||seenDays.has(day)){skipped.push('existing or duplicate day: '+day);continue}\n  seenIds.add(id);seenDays.add(day);\n  const reference=String(d.reference).trim();\n  valid.push({id,day,title:String(d.title).trim(),topics:Array.isArray(d.topics)?d.topics.map(String).map(t=>t.trim()).filter(Boolean):String(d.topics||'').split(',').map(t=>t.trim()).filter(Boolean),reference,bibleUrl:scriptureUrl(reference),short:String(d.short).trim(),deeper:String(d.deeper).trim(),reflection:String(d.reflection||'').trim(),status:'draft'});\n }\n if(!valid.length){message('Nothing imported. All '+entries.length+' entries were duplicates or missing required fields. Existing devotionals were unchanged.',true);return}\n const summary='Import '+valid.length+' devotionals as DRAFTS?'+(skipped.length?' '+skipped.length+' will be skipped (duplicate ID/day or invalid data).':'')+' Existing devotionals will not be replaced.';\n if(!confirm(summary))return;\n const button=$('#bulkImport');button.disabled=true;\n let imported=0,failed=[];\n try{\n  for(const d of valid){\n   message('Importing '+(imported+failed.length+1)+' of '+valid.length+': '+d.title);\n   try{await api('/api/admin/devotionals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(d)});imported++}\n   catch(err){failed.push(d.title+': '+err.message)}\n  }\n }finally{\n  await refresh();\n  const parts=[imported+' imported as drafts',skipped.length+' skipped',failed.length+' failed'];\n  message('Bulk import finished: '+parts.join(', ')+'.'+(failed.length?' Failed: '+failed.slice(0,3).join('; '):''),failed.length>0);\n }\n}\n\nlet selectedIds=new Set(),statusBusy=false;\nconst statusPayload=d=>({\n id:d.id,day:d.day,title:d.title,topics:d.topics,reference:d.reference,\n bibleUrl:d.bibleUrl||scriptureUrl(d.reference),short:d.short,\n deeper:d.deeper,reflection:d.reflection||'',author:d.author||'Heather Kusunoki',status:d.status\n});\nfunction updateSelectionControls(){\n const count=selectedIds.size;\n const countEl=$('#selectionCount');\n if(countEl)countEl.textContent=count+' selected';\n const publish=$('#publishSelected'),unpublish=$('#unpublishSelected');\n if(publish)publish.disabled=statusBusy||!count;\n if(unpublish)unpublish.disabled=statusBusy||!count;const remove=$('#deleteSelected');if(remove)remove.disabled=statusBusy||!count;\n const all=$('#selectAll');\n if(all){all.checked=items.length>0&&count===items.length;all.indeterminate=count>0&&count<items.length}\n}\nasync function changePublicationStatus(ids,status){\n const targets=items.filter(d=>ids.includes(String(d.id))&&d.status!==status);\n if(!targets.length){message('No changes needed. The selected entries already have that status.');return}\n const verb=status==='published'?'publish':'unpublish';\n if(!confirm((status==='published'?'Publish ':'Unpublish ')+targets.length+' selected devotional'+(targets.length===1?'':'s')+'?'+(status==='published'?' They will become visible on the public website.':' They will be removed from the public devotional list.')))return;\n statusBusy=true;updateSelectionControls();\n let done=0,errors=[];\n try{\n  for(const d of targets){\n   message((status==='published'?'Publishing ':'Unpublishing ')+(done+errors.length+1)+' of '+targets.length+': '+d.title);\n   try{\n    await api('/api/admin/devotionals',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(statusPayload({...d,status}))});\n    done++;\n   }catch(e){errors.push(d.title+': '+e.message)}\n  }\n }finally{\n  statusBusy=false;\n  selectedIds.clear();\n  await refresh();\n  message(done+' '+(status==='published'?'published':'unpublished')+'.'+(errors.length?' '+errors.length+' failed: '+errors.slice(0,3).join('; '):''),errors.length>0);\n }\n}\nfunction render(){\n selectedIds=new Set([...selectedIds].filter(id=>items.some(d=>String(d.id)===id)));\n const pub=items.filter(x=>x.status==='published').length;\n $('#adminApp').innerHTML=`\n <style>\n .whdc-toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:12px 0}\n .whdc-toolbar .btn,.whdc-row-actions .btn{font-size:.83rem;padding:7px 11px;min-height:34px}\n .whdc-secondary{display:flex;gap:6px;flex-wrap:wrap;align-items:center}\n .whdc-selection{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 10px;border:1px solid #d8ded8;border-radius:10px;margin:14px 0;background:#f6f8f5}\n .whdc-selection label{display:inline-flex;align-items:center;gap:6px;margin:0;cursor:pointer}\n .whdc-selection input[type=checkbox],.whdc-row input[type=checkbox]{width:17px;height:17px;flex-shrink:0;accent-color:#527c6d;cursor:pointer}\n .whdc-row{display:flex;align-items:center;gap:13px;padding:12px 9px;border-bottom:1px solid #e5e9e5}\n .whdc-row-body{flex:1;min-width:0}\n .whdc-row-actions{display:flex;gap:6px;flex-wrap:wrap}\n .whdc-status{font-weight:600}\n .whdc-status.published{color:#306b4f}\n .whdc-status.draft{color:#85692c}\n @media(max-width:600px){.whdc-row{align-items:flex-start;flex-wrap:wrap}.whdc-row-actions{width:100%;padding-left:30px}.whdc-toolbar .btn{font-size:.78rem;padding:7px 9px}}\n </style>\n <div class=\"notice\"><strong>${pub} published</strong> · ${items.length-pub} drafts</div>\n <p id=\"message\" aria-live=\"polite\"></p>\n <div class=\"whdc-toolbar\" aria-label=\"Writing dashboard tools\">\n  <a class=\"btn\" href=\"/admin/outline\">Master Outline</a> <button class=\"btn primary\" id=\"new\" type=\"button\">+ New</button>\n  <button class=\"btn\" id=\"bulkImport\" type=\"button\">Import JSON</button>\n  <input id=\"bulkImportFile\" type=\"file\" accept=\".json,application/json\" style=\"display:none\" aria-label=\"Choose devotionals JSON file\">\n  <div class=\"whdc-secondary\">\n   <button class=\"btn\" id=\"exportPdf\" type=\"button\">PDF</button>\n   <button class=\"btn\" id=\"exportCsv\" type=\"button\">CSV</button>\n   <button class=\"btn\" id=\"exportJson\" type=\"button\">Backup JSON</button>\n  </div>\n </div>\n <div class=\"whdc-selection\" aria-label=\"Select devotionals to publish or unpublish\">\n  <label><input type=\"checkbox\" id=\"selectAll\"> Select all</label>\n  <span id=\"selectionCount\" class=\"small muted\">0 selected</span>\n  <button class=\"btn primary\" id=\"publishSelected\" type=\"button\" disabled>Publish selected</button>\n  <button class=\"btn\" id=\"unpublishSelected\" type=\"button\" disabled>Unpublish selected</button>\n  <button class=\"btn\" id=\"deleteSelected\" type=\"button\" disabled style=\"color:#9b3d36\">Delete selected</button>\n  <button class=\"btn\" id=\"clearSelection\" type=\"button\">Clear</button>\n </div>\n <div class=\"admin-list\">${items.map(d=>`\n  <div class=\"whdc-row\">\n   <input type=\"checkbox\" class=\"whdc-select\" data-select=\"${safe(d.id)}\" aria-label=\"Select ${safe(d.title)}\" ${selectedIds.has(String(d.id))?'checked':''}>\n   <div class=\"whdc-row-body\">\n    <strong>${safe(d.title)}</strong>\n    <div class=\"small muted\">Day ${safe(d.day)} · ${safe(d.reference)} · <span class=\"whdc-status ${d.status==='published'?'published':'draft'}\">${d.status==='published'?'Published':'Draft'}</span></div>\n   </div>\n   <div class=\"whdc-row-actions\">\n    <button class=\"btn\" type=\"button\" data-status-id=\"${safe(d.id)}\">${d.status==='published'?'Unpublish':'Publish'}</button>\n    <button class=\"btn\" type=\"button\" data-edit=\"${safe(d.id)}\">Edit</button>\n    <button class=\"btn\" type=\"button\" data-delete=\"${safe(d.id)}\">Delete</button>\n   </div>\n  </div>`).join('')||'<p>No devotionals yet. Create one or import a JSON file.</p>'}</div>\n <div id=\"editArea\"></div>`;\n $('#new').onclick=()=>edit(null);\n $('#bulkImport').onclick=()=>$('#bulkImportFile').click();\n $('#bulkImportFile').onchange=importBulkDevotionals;\n $('#exportCsv').onclick=()=>exportDevotionals('csv');\n $('#exportJson').onclick=()=>exportDevotionals('json');\n $('#exportPdf').onclick=exportPdf;\n $('#selectAll').onchange=e=>{selectedIds=e.target.checked?new Set(items.map(d=>String(d.id))):new Set();document.querySelectorAll('.whdc-select').forEach(c=>c.checked=e.target.checked);updateSelectionControls()};\n $('#clearSelection').onclick=()=>{selectedIds.clear();document.querySelectorAll('.whdc-select').forEach(c=>c.checked=false);updateSelectionControls()};\n document.querySelectorAll('.whdc-select').forEach(c=>c.onchange=()=>{if(c.checked)selectedIds.add(c.dataset.select);else selectedIds.delete(c.dataset.select);updateSelectionControls()});\n $('#publishSelected').onclick=()=>changePublicationStatus([...selectedIds],'published');\n $('#unpublishSelected').onclick=()=>changePublicationStatus([...selectedIds],'draft');\n $('#deleteSelected').onclick=async()=>{\n  const ids=[...selectedIds];if(!ids.length)return;\n  if(!confirm('Permanently delete '+ids.length+' selected devotional'+(ids.length===1?'':'s')+'? This cannot be undone. Export a JSON backup first if needed.'))return;\n  const button=$('#deleteSelected');button.disabled=true;\n  let deleted=0,failed=[];\n  for(const id of ids){try{await api('/api/admin/delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id})});selectedIds.delete(id);deleted++}catch(e){failed.push(id+': '+e.message)}}\n  await refresh();message(deleted+' devotional'+(deleted===1?'':'s')+' deleted.'+(failed.length?' '+failed.length+' failed: '+failed.slice(0,3).join('; '):''),failed.length>0);\n };\n document.querySelectorAll('[data-status-id]').forEach(b=>b.onclick=()=>{\n  const d=items.find(x=>String(x.id)===b.dataset.statusId);\n  if(d)changePublicationStatus([String(d.id)],d.status==='published'?'draft':'published');\n });\n document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(items.find(d=>d.id===b.dataset.edit)));\n document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{\n  if(!confirm('Permanently delete this devotional from the database?'))return;\n  try{await api('/api/admin/delete',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({id:b.dataset.delete})});await refresh();message('Devotional deleted.')}\n  catch(e){message(e.message,true)}\n });\n updateSelectionControls();\n}\napi('/api/admin/me').then(me=>{writerName=me.displayName||'Heather Kusunoki'}).catch(()=>{}).finally(async()=>{await refresh();const q=new URLSearchParams(location.search);if(q.has('edit')){const d=items.find(x=>x.id===q.get('edit'));if(d)edit(d)}else if(q.has('newTitle')){edit({title:q.get('newTitle'),topics:q.get('topic')?[q.get('topic')]:[],day:items.length+1})}});\n\n(function(){\n const toggle=document.getElementById('dashboardMenuToggle'),menu=document.getElementById('dashboardMenu');\n if(!toggle||!menu)return;\n const close=()=>{menu.hidden=true;toggle.setAttribute('aria-expanded','false')};\n toggle.addEventListener('click',()=>{menu.hidden=!menu.hidden;toggle.setAttribute('aria-expanded',String(!menu.hidden))});\n document.addEventListener('click',e=>{if(!menu.hidden&&!menu.contains(e.target)&&!toggle.contains(e.target))close()});\n document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});\n})();\n";

